style.css:
@-moz-document domain("google.com") {
/* 1. Скругленные углы (ключевой элемент MIUI) */
    .RNNXgb {
        border-radius: 24px !important; /* Делаем поисковую строку очень скругленной */
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1) !important; /* Добавляем мягкую тень */
        border: none !important;
    }

    /* 2. Чистый шрифт (близкий к MI Sans/Roboto) */
    body {
        font-family: Roboto, "Helvetica Neue", Arial, sans-serif !important; 
        /* Roboto - это шрифт, который лежит в основе большинства дизайнов MIUI */
    }

    /* 3. Голубой/Светло-голубой акцентный цвет */
    .gNO89b, .Tg7LZd, .z1asce {
        background-color: #0084ff !important; /* Основной голубой цвет Xiaomi */
        border: none !important;
        color: white !important;
        border-radius: 8px !important; /* Слегка скругляем кнопки */
    }
}
